using Xunit;

public class CalculatorTests
{
    [Fact]
    public void Add_TwoPositiveNumbers_ReturnsSum()
    {
        // Arrange — set up the test subject and inputs
        var calculator = new Calculator();
        int a = 2;
        int b = 3;

        // Act — execute the method being tested
        int result = calculator.Add(a, b);

        // Assert — verify the result is correct
        Assert.Equal(5, result);
    }

    [Fact]
    public void Divide_ByZero_ThrowsDivideByZeroException()
    {
        var calculator = new Calculator();

        Assert.Throws<DivideByZeroException>(() => calculator.Divide(10, 0));
    }
}

public class Calculator
{
    public int Add(int a, int b) => a + b;
    public int Divide(int a, int b) => a / b;
}

public class CalculatorTests
{
    [Theory]
    [InlineData(1, 1, 2)]
    [InlineData(0, 5, 5)]
    [InlineData(-3, 7, 4)]
    [InlineData(100, -50, 50)]
    public void Add_MultipleInputs_ReturnsExpectedSum(int a, int b, int expected)
    {
        var calculator = new Calculator();

        int result = calculator.Add(a, b);

        Assert.Equal(expected, result);
    }
}

// This single test method runs 4 times — once per InlineData
// Each run is reported as a separate test result
